<?php
use App\DonationPaymentMethod; use App\DonationPaymentStatus; use App\DonationSource; use App\Models\Donation; use App\Models\DonationCampaign; use App\Models\DonationCategory; use App\Models\Donor; use Illuminate\Contracts\Pagination\LengthAwarePaginator; use Illuminate\Database\Eloquent\Builder; use Illuminate\Support\Facades\Gate; use Livewire\Attributes\Computed; use Livewire\Attributes\Title; use Livewire\Attributes\Url; use Livewire\Component; use Livewire\WithPagination;
new #[Title('Donations')] class extends Component { use WithPagination; #[Url] public string $search=''; #[Url] public string $status=''; #[Url] public string $category=''; #[Url] public string $method=''; #[Url] public string $source=''; #[Url] public string $from=''; #[Url] public string $to=''; #[Url] public string $sort='donated_at'; #[Url] public string $direction='desc'; public int $perPage=20;
 public function mount():void{Gate::authorize('viewAny',Donation::class);} public function updated():void{$this->resetPage();} public function clearFilters():void{$this->reset(['search','status','category','method','source','from','to']);$this->resetPage();}
 #[Computed] public function donations():LengthAwarePaginator{return Donation::query()->with(['donor:id,first_name,last_name,is_anonymous','category:id,name','campaign:id,name','recorder:id,name'])->when($this->search,fn(Builder $q)=>$q->search($this->search))->when($this->status,fn(Builder $q)=>$q->where('payment_status',$this->status))->when($this->category,fn(Builder $q)=>$q->where('donation_category_id',$this->category))->when($this->method,fn(Builder $q)=>$q->where('payment_method',$this->method))->when($this->source,fn(Builder $q)=>$q->where('source',$this->source))->when($this->from,fn(Builder $q)=>$q->whereDate('donated_at','>=',$this->from))->when($this->to,fn(Builder $q)=>$q->whereDate('donated_at','<=',$this->to))->orderBy(in_array($this->sort,['amount','donated_at','created_at'],true)?$this->sort:'donated_at',$this->direction==='asc'?'asc':'desc')->paginate($this->perPage);}
 #[Computed] public function stats():array{$completed=Donation::completed();$total=(string)(clone $completed)->sum('amount');$count=(clone $completed)->count();return ['total'=>$total,'month'=>(string)(clone $completed)->whereBetween('donated_at',[now()->startOfMonth(),now()->endOfMonth()])->sum('amount'),'year'=>(string)(clone $completed)->whereYear('donated_at',now()->year)->sum('amount'),'pending'=>Donation::where('payment_status',DonationPaymentStatus::Pending)->count(),'donors'=>Donor::count(),'campaigns'=>DonationCampaign::where('status','active')->count(),'average'=>$count?(string)((float)$total/$count):'0','refunded'=>(string)\App\Models\DonationRefund::sum('amount')];}
 public function categories(){return DonationCategory::orderBy('name')->get(['id','name']);}
}; ?>
